import presets from './scrumPresets.json';
import type { BoardView, LaneId, Layout, PlayerTuple, Possession, RowId } from '../board/types';
import { tuplesToPlayers } from '../board/constants';
import { withBacklines } from './scrumBackline';

/**
 * Scrum presets copied verbatim from rugbytacticsboard.com ("Standard Scrum Setups").
 * 7 field rows x 5 lanes = 35 locations, each with an attacking and a defending variant.
 * The site's forwards and 9s are used as-is; both backlines are regenerated by scrumBackline.ts
 * from who has the ball, since the site's "defensive" variant only moves the 9s.
 */

export interface LaneDef {
  id: LaneId;
  label: string;
  shortLabel: string;
  x: number;
}
export interface RowDef {
  id: RowId;
  label: string;
  shortLabel: string;
  y: number;
  boardView: BoardView;
}

export const LANES: LaneDef[] = [
  { id: 'left5', label: 'Left 5m', shortLabel: 'L5', x: 115 },
  { id: 'left15', label: 'Left 15m', shortLabel: 'L15', x: 280 },
  { id: 'centre', label: 'Centre', shortLabel: 'C', x: 550 },
  { id: 'right15', label: 'Right 15m', shortLabel: 'R15', x: 820 },
  { id: 'right5', label: 'Right 5m', shortLabel: 'R5', x: 985 },
];

export const ROWS: RowDef[] = [
  { id: 'top5', label: 'Opp. 5m', shortLabel: '5m', y: 130, boardView: 'pitchIn' },
  { id: 'top22', label: 'Opp. 22m', shortLabel: '22', y: 310, boardView: 'pitchIn' },
  { id: 'top10', label: 'Opp. 10m', shortLabel: '10', y: 480, boardView: 'pitchIn' },
  { id: 'halfway', label: 'Halfway', shortLabel: 'H', y: 350, boardView: 'pitchMiddle' },
  { id: 'bottom10', label: 'Own 10m', shortLabel: '10', y: 215, boardView: 'pitchOut' },
  { id: 'bottom22', label: 'Own 22m', shortLabel: '22', y: 390, boardView: 'pitchOut' },
  { id: 'bottom5', label: 'Own 5m', shortLabel: '5m', y: 565, boardView: 'pitchOut' },
];

interface RawSetup {
  id: string;
  label: string;
  boardView: string;
  attacking: { ball: { x: number; y: number }; players: unknown[] };
  defensive: { ball: { x: number; y: number }; players: unknown[] };
}

const SETUPS = presets as Record<string, RawSetup>;

export const scrumSetupId = (row: RowId, lane: LaneId) => `${row}-${lane}`;

export function scrumLayout(row: RowId, lane: LaneId, possession: Possession): Layout {
  const setup = SETUPS[scrumSetupId(row, lane)] ?? SETUPS['halfway-left15'];
  const variant = possession === 'defending' ? setup.defensive : setup.attacking;
  return {
    boardView: setup.boardView as BoardView,
    ball: { ...variant.ball },
    players: tuplesToPlayers(withBacklines(variant.players as PlayerTuple[], row, possession)),
  };
}

export const scrumSetupLabel = (row: RowId, lane: LaneId) =>
  SETUPS[scrumSetupId(row, lane)]?.label ?? `${row}, ${lane}`;
